```python
async def garde_fou(input_data, tool_use_id, context):
    if input_data.get("tool_name") == "poser_conge":
        a = input_data["tool_input"]
        if jours_ouvres(date.fromisoformat(a["debut"]), date.fromisoformat(a["fin"])) > 10:
            return {"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny",
                    "permissionDecisionReason": "Plus de 10 jours ouvrés : validation manager requise."}}
    return {}

options = ClaudeAgentOptions(
